contract:
- name: Validate persisted PFC-keyed Hero repository
  run: |
    node - <<'JS'
    const fs=require('fs');
    const H=require('./site/hero-ranges.js');
    const path='training/runs/20260917_hero_preflop_169_btn_unopened_pfc_v1/HERO_RANGE_REPOSITORY_PFC.json';
    const repo=JSON.parse(fs.readFileSync(path,'utf8'));
    H.validateRepository(repo);
    const stats=H.repositoryStats(repo);
    if(stats.contexts!==1||stats.calculated_defined_hands!==40||stats.personal_defined_hands!==0){
      throw new Error(JSON.stringify(stats));
    }
    const key=Object.keys(repo.contexts)[0];
    if(!key.endsWith('|PFC_0e01f7d1a1da491b'))throw new Error(key);
    console.log(stats);
    JS

